  export function faceBody(key) { return TILE_ART[key] || ""; }

  /* 牌面做成一张「雪碧图」：42 种牌面在页面里只画一次，藏进 <defs>，
     每张牌只留一个 <use> 引过去。一张牌从 ~17 个 DOM 节点降到 2 个，
     牌河重排时要交给浏览器解析的 HTML 少一个数量级，老手机上差别很明显。 */
  export var spriteReady = false;
  export function buildTileSprite() {
    if (spriteReady) return;
    var keys = KEYS34.slice(), k;
    for (k in FLOWER) if (FLOWER.hasOwnProperty(k)) keys.push(k);
    var defs = "";
    for (var i = 0; i < keys.length; i++) {
      defs += '<g id="tf-' + keys[i] + '">' + faceBody(keys[i]) + "</g>";
    }
    var host = document.createElement("div");
    host.setAttribute("aria-hidden", "true");
    host.style.cssText = "position:absolute;width:0;height:0;overflow:hidden";
    host.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0">' +
                     "<defs>" + defs + "</defs></svg>";
    document.body.insertBefore(host, document.body.firstChild);
    spriteReady = true;
  }

  export function tileFace(key) {
    if (!FACE_CACHE[key]) {
      /* 同时写 href 和 xlink:href：老一点的 Safari 只认后者 */
      FACE_CACHE[key] = '<svg viewBox="0 0 60 82" aria-hidden="true"><use href="#tf-' + key +
                        '" xlink:href="#tf-' + key + '"/></svg>';
    }
    return FACE_CACHE[key];
  }

  export function mjHTML(key, opt) {
    opt = opt || {};
    var cls = "mj" + (opt.size ? " " + opt.size : "") + (opt.back ? " back" : "") +
              (opt.sel ? " sel" : "") + (opt.last ? " last" : "") + (opt.drop ? " drop" : "");
    var attrs = ' class="' + cls + '"' +
                (opt.id != null ? ' data-id="' + opt.id + '"' : "") +
                ' data-key="' + key + '"';
    if (opt.back) return "<div" + attrs + "></div>";
    return "<div" + attrs + "><i class=\"face\"></i>" + tileFace(key) + "</div>";
  }
